parameters.body:
={
  "model": "gemma3:12b",
  "prompt": "You are a Notary Service Assistant. Your task is to analyze incoming emails and determine if they are requests for notary or loan signing services. CRITICAL RULE: If the email contains ANY mention of 'notary', 'notarize', 'loan signing', 'signing agent', 'closing', or 'documents to sign', you MUST set isNotaryRequest to true. Extract the following fields if available, otherwise use 'Not provided': - clientName, - serviceType, - preferredDateTime, - location, - phone. Return ONLY a valid JSON object with these keys: isNotaryRequest (boolean), clientName (string), serviceType (string), preferredDateTime (string), location (string), phone (string). Email Subject: {{ ($json.Subject || $json.subject || '').replace(/"/g, '\\"').replace(/\n/g, ' ') }} Email Body: {{ ($json.textPlain || $json.snippet || '').replace(/"/g, '\\"').replace(/\n/g, ' ') }}",
  "format": "json",
  "stream": false
}

parameters.jsCode:
try {
  return $input.all().map((item) => {
    const text = item.json.response;
    const data = JSON.parse(text);
    const triggerData = $('Gmail Trigger').all()[item.pairedItem.item].json;
    const subject = (triggerData.Subject || triggerData.subject || '').toLowerCase();
    const body = (triggerData.textPlain || triggerData.snippet || '').toLowerCase();
    const keywords = ['notary', 'notarize', 'loan signing', 'signing agent', 'closing'];
    if (!data.isNotaryRequest) {
      if (keywords.some(k => subject.includes(k) || body.includes(k))) {
        data.isNotaryRequest = true;
      }
    }
    // Extract sender name from From field as fallback
    const fromRaw = triggerData.From?.value || triggerData.From || triggerData.from?.value || triggerData.from || '';
    const fromStr = typeof fromRaw === 'string' ? fromRaw : (fromRaw[0]?.name || fromRaw[0]?.address || '');
    const nameMatch = fromStr.match(/^([^<]+)</  );
    const senderName = nameMatch ? nameMatch[1].trim() : fromStr.split('@')[0];
    if (!data.clientName || data.clientName === 'Not provided') {
      data.clientName = senderName || 'Not provided';
    }
    data.originalSender = fromStr;
    data.originalSubject = triggerData.Subject || triggerData.subject;
    return { json: data };
  });
} catch (e) {
  return [{ json: { isNotaryRequest: false, error: e.message } }];
}

